import java.lang.reflect.*;

interface Repo { void find(); }
class RepoImpl implements Repo { public void find() { System.out.println("  [target] RepoImpl.find executed"); } }
class Handler implements InvocationHandler {
    Object target;
    Handler(Object t) { target = t; }
    public Object invoke(Object proxy, Method m, Object[] args) throws Throwable {
        System.out.println("this is a JDK proxy: " + Proxy.isProxyClass(proxy.getClass()));
        System.out.println("target is the real bean: " + target.getClass().getSimpleName());
        System.out.println("proxy == target ? " + (proxy == target));
        return m.invoke(target, args);
    }
}
public class Main {
    public static void main(String[] a) throws Exception {
        Repo proxy = (Repo) Proxy.newProxyInstance(Repo.class.getClassLoader(),
            new Class[]{Repo.class}, new Handler(new RepoImpl()));
        proxy.find();
    }
}
